-- =============================================================================
-- revenue_concentration
-- Purpose : Share of net revenue generated by the top X% of customers.
-- Params  : :start_date, :end_date (+ segment filter params)
-- Returns : one row per tier (top 1%, 5%, 10%, 20%, 50%)
-- SQL     : CTE built from a VALUES list, HAVING, ROW_NUMBER(), COUNT()/SUM()
--           OVER (), CROSS JOIN, conditional aggregation
-- Notes   : Customers with net revenue <= 0 (fully refunded) are excluded.
--           Tier size = CEIL(N * p / 100) with a minimum of one customer.
-- =============================================================================
WITH tx AS MATERIALIZED (
    {{FILTERED_TX}}
),
customer_net AS (
    SELECT customer_id, SUM(revenue) AS net_revenue
    FROM tx
    GROUP BY customer_id
    HAVING SUM(revenue) > 0
),
ranked AS (
    SELECT
        customer_id,
        net_revenue,
        ROW_NUMBER() OVER (ORDER BY net_revenue DESC, customer_id) AS rn,
        COUNT(*)         OVER ()                                   AS n_customers,
        SUM(net_revenue) OVER ()                                   AS total_net
    FROM customer_net
),
tiers(top_pct) AS (
    VALUES (1), (5), (10), (20), (50)
),
tier_members AS (
    SELECT
        t.top_pct,
        r.n_customers,
        r.total_net,
        CASE WHEN r.rn <= MAX(1, CAST(r.n_customers * t.top_pct / 100.0 + 0.999999 AS INTEGER))
             THEN r.net_revenue END AS member_revenue
    FROM tiers t
    CROSS JOIN ranked r
)
SELECT
    top_pct,
    MAX(n_customers)                                         AS customer_base,
    COUNT(member_revenue)                                    AS customers_in_tier,
    ROUND(SUM(COALESCE(member_revenue, 0)), 2)               AS tier_revenue,
    ROUND(100.0 * SUM(COALESCE(member_revenue, 0)) / MAX(total_net), 2) AS revenue_share_pct
FROM tier_members
GROUP BY top_pct
ORDER BY top_pct;
